  <div class="page">
    <div class="card">
      <header class="card-header">
        <h1 class="card-title">Formulaire fournisseur</h1>
      </header>
      <form>
        <div class="field">
          <label for="raison_sociale">Raison sociale</label>
          <input type="text" id="raison_sociale" required />
        </div>
        <div class="field">
          <label for="contact_principal">Contact principal</label>
          <input type="text" id="contact_principal" required />
        </div>
        <div class="field">
          <label for="email">Email</label>
          <input type="email" id="email" required />
        </div>
        <div class="field">
          <label for="telephone">Téléphone</label>
          <input type="tel" id="telephone" required />
        </div>
        <div class="field">
          <label for="adresse">Adresse</label>
          <input type="text" id="adresse" required />
        </div>
        <div class="field">
          <label for="pays">Pays</label>
          <input type="text" id="pays" required />
        </div>
        <div class="field">
          <label for="conditions_de_paiement">Conditions de paiement</label>
          <textarea id="conditions_de_paiement" required></textarea>
        </div>
        <div class="field">
          <label for="iban">IBAN</label>
          <input type="text" id="iban" required />
        </div>
        <div class="field">
          <label for="notes">Notes</label>
          <textarea id="notes"></textarea>
        </div>
        <div class="actions">
          <button type="submit" class="btn-primary">Enregistrer</button>
          <button type="button" class="btn-secondary">Annuler</button>
        </div>
      </form>
    </div>
  </div>
</body>
